"""Coverage for defect #11's two easy DOCX-generation gaps:

- No page-size parameter: python-docx's bundled template defaults to US
  Letter (215.9mm x 279.4mm); every Israeli academic document is A4. A4 is
  now generate_docx()'s default, with an explicit "Letter" opt-out.
- `margins` was inches-only with no unit field: passing 2.5 meaning
  centimetres silently produced 5" of margin on Letter (a 3.5" text
  column). `marginsUnit` ("in" default, or "cm") makes the interpretation
  explicit.
"""

from __future__ import annotations

import importlib.util
import os
import tempfile
import unittest
import zipfile

from docx import Document

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCRIPTS_DIR = os.path.join(ROOT_DIR, "src", "scripts")

EMU_PER_MM = 36000
EMU_PER_INCH = 914400


def _load_generate_docx_module():
    script_path = os.path.join(SCRIPTS_DIR, "generate-docx.py")
    spec = importlib.util.spec_from_file_location("generate_docx_module_page_format_test", script_path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _generate(module, fmt_overrides):
    data = {
        "title": "בדיקה",
        "totalWords": 100,
        "format": {"isRtl": True, **fmt_overrides},
        "sections": [{"title": "מבוא", "paragraphs": ["פסקה קצרה."]}],
    }
    with tempfile.TemporaryDirectory() as tmpdir:
        output_path = os.path.join(tmpdir, "out.docx")
        module.generate_docx(data, output_path)
        return Document(output_path)


class PageSizeTests(unittest.TestCase):
    def setUp(self):
        self.module = _load_generate_docx_module()

    def test_default_page_size_is_a4_not_letter(self):
        doc = _generate(self.module, {})
        section = doc.sections[0]
        self.assertAlmostEqual(section.page_width, round(210 * EMU_PER_MM), delta=1000)
        self.assertAlmostEqual(section.page_height, round(297 * EMU_PER_MM), delta=1000)

    def test_letter_opt_out_still_available(self):
        doc = _generate(self.module, {"pageSize": "Letter"})
        section = doc.sections[0]
        self.assertAlmostEqual(section.page_width, round(8.5 * EMU_PER_INCH), delta=1000)
        self.assertAlmostEqual(section.page_height, round(11 * EMU_PER_INCH), delta=1000)


class MarginsUnitTests(unittest.TestCase):
    def setUp(self):
        self.module = _load_generate_docx_module()

    def test_default_margins_unit_is_inches_backward_compatible(self):
        doc = _generate(self.module, {"margins": 1.0})
        section = doc.sections[0]
        self.assertEqual(section.top_margin, round(1.0 * EMU_PER_INCH))

    def test_centimetre_margins_are_not_silently_misinterpreted_as_inches(self):
        # The exact reported trap: 2.5 meaning centimetres produced 5" of
        # margin (2.5in) when the value was taken as inches unconditionally.
        doc_cm = _generate(self.module, {"margins": 2.5, "marginsUnit": "cm"})
        doc_in_for_comparison = _generate(self.module, {"margins": 2.5, "marginsUnit": "in"})
        section_cm = doc_cm.sections[0]
        section_in = doc_in_for_comparison.sections[0]
        self.assertNotEqual(section_cm.top_margin, section_in.top_margin)
        self.assertAlmostEqual(section_cm.top_margin, round(2.5 * 360000), delta=1000)  # Cm(2.5) in EMU


if __name__ == "__main__":
    unittest.main()
